// Push notifications aren't supported everywhere (older Safari, non-secure
// contexts, etc.) and firebase.messaging() throws in those cases — this
// returns null instead of letting that crash the app.
export const getMessagingInstance = () => {
  try {
    if (firebase.messaging.isSupported && !firebase.messaging.isSupported()) {
      return null;
    }
    return firebase.messaging();
  } catch (err) {
    return null;
  }
};

