import './App.css';
import { useState, useRef, useEffect, useLayoutEffect, useCallback, Fragment } from 'react';
import db, { firebase, getMessagingInstance } from './utils/firebase';
import VideoCall from './VideoCall';
import BirthdayFireworks from './BirthdayFireworks';
import BirthdayIntro from './BirthdayIntro';
import moment from 'moment';
import BarLoader from "react-spinners/BarLoader";

const PAGE_SIZE = 100;
const LOAD_MORE_SIZE = 50;
const NEAR_BOTTOM_THRESHOLD = 80;
const TYPING_IDLE_MS = 2000;
// Only a crash-recovery safety net (e.g. the tab closes mid-typing-burst
// without ever writing typing:false) — not a freshness gate, since a typing
// burst only writes updatedAt once at its start, not on every keystroke.
const TYPING_STALE_MS = 15000;
const TYPING_COLLECTION = 'typingStatus';
const READ_RECEIPTS_COLLECTION = 'readReceipts';
const QUICK_REACTIONS = ['❤️', '😂', '😮', '😢', '👍', '🔥'];
const SWIPE_REPLY_THRESHOLD = 56;

// Push notifications are a client + Cloud Function pair (see
// functions/index.js) and are deliberately limited to one recipient.
const NOTIFICATIONS_ENABLED_USER = 'Ananthu';
// Firebase Console → Project settings → Cloud Messaging → Web Push
// certificates → generate a key pair, then paste it here.
const FCM_VAPID_KEY = 'BM0-iWbfyWkWlWmu2WyLVIpDjObIJa4YtiBTnwlUAKOCyj9gxs_WMM4CzoR52tv0v6V0PHMKeBs5e46VWh6l8YA';

// Symbols like the heart (U+2764) render as a monochrome "text style" glyph
// inheriting the surrounding text color unless followed by the U+FE0F
// variation selector, which forces the full-color "emoji style" glyph.
// Built from raw code points (rather than literal characters) to keep the
// exact symbols unambiguous: Misc Symbols + Dingbats (2600-27BF) and Misc
// Symbols and Arrows (2B00-2BFF) cover the common ones typed without a
// variation selector, e.g. the heart at 2764.
const VARIATION_SELECTOR_16 = String.fromCodePoint(0xFE0F);
const AMBIGUOUS_EMOJI_REGEX = new RegExp(
  '[' +
    String.fromCodePoint(0x2600) + '-' + String.fromCodePoint(0x27bf) +
    String.fromCodePoint(0x2b00) + '-' + String.fromCodePoint(0x2bff) +
  ']' + VARIATION_SELECTOR_16 + '?',
  'gu'
);
const forceEmojiPresentation = (text) =>
  text.replace(AMBIGUOUS_EMOJI_REGEX, (char) => char[0] + VARIATION_SELECTOR_16);

// Set this to a SPECIAL_DATES id below (e.g. 'anniversary') to preview that
// theme regardless of today's date. Leave null for normal date-based behavior.
const DEBUG_FORCE_SPECIAL_DATE_ID = null;

const SPECIAL_DATES = [
  {
    id: 'anniversary',
    month: 8, // September (0-indexed)
    day: 16,
    themeClass: 'anniversary-theme',
    particles: ['💕', '💖', '💗', '✨', '🎉'],
    banner: "💕 Happy Anniversary 💕 — here's to many more",
    loginTag: '💕 Happy Anniversary 💕',
  },
  // Add more special days the same way, e.g.:
  {
    id: 'birthday',
    month: 9, day: 16,
    themeClass: 'birthday-theme',
    particles: ['🎂', '🎈', '🎉', '✨', '🥳'],
    banner: '🎂 Happy Birthday Cutie 🎂',
    loginTag: '🎂 Happy Birthday 🎂',
  },
];

const getActiveSpecialDate = () => {
  if (DEBUG_FORCE_SPECIAL_DATE_ID) {
    return SPECIAL_DATES.find(d => d.id === DEBUG_FORCE_SPECIAL_DATE_ID) || null;
  }
  const today = new Date();
  return SPECIAL_DATES.find(d => d.month === today.getMonth() && d.day === today.getDate()) || null;
};

const getDayLabel = (timestamp) => {
  const m = moment(timestamp);
  if (m.isSame(moment(), 'day')) return 'Today';
  if (m.isSame(moment().subtract(1, 'day'), 'day')) return 'Yesterday';
  return m.format('MMMM D, YYYY');
};

function App() {
  const [user, setUser] = useState('');
  const [password, setPassword] = useState('');
  const [message, setMessage] = useState('');
  const [isLogin, setIsLogin] = useState(true);
  const [birthdayIntroDone, setBirthdayIntroDone] = useState(false);
  const [loginError, setLoginError] = useState('');
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(false);
  const [loadingMore, setLoadingMore] = useState(false);
  const [heartParticles, setHeartParticles] = useState([]);
  const [typingUsers, setTypingUsers] = useState([]);
  const [callButtonTarget, setCallButtonTarget] = useState(null);
  const [keyboardOpen, setKeyboardOpen] = useState(false);
  const [readReceipts, setReadReceipts] = useState({});
  const [activeMessageId, setActiveMessageId] = useState(null);
  const [replyingTo, setReplyingTo] = useState(null);
  const [hasUnseenMessages, setHasUnseenMessages] = useState(false);
  const [hasMoreMessages, setHasMoreMessages] = useState(true);

  const hasMoreRef = useRef(true);
  const oldestDocRef = useRef(null);
  const cursorInitializedRef = useRef(false);
  const messagesContainerRef = useRef(null);
  const chatContainerRef = useRef(null);
  const pendingScrollAdjustRef = useRef(null);
  const isInitialLoadRef = useRef(true);
  const isNearBottomRef = useRef(true);
  const heartIdRef = useRef(0);
  const typingTimeoutRef = useRef(null);
  const isTypingRef = useRef(false);
  const lastWrittenReadAtRef = useRef(0);
  const lastSeenNewestIdRef = useRef(null);
  const swipeStateRef = useRef(null);
  const suppressClickRef = useRef(false);

  const specialDate = getActiveSpecialDate();
  const showBirthdayIntro = isLogin && specialDate && specialDate.id === 'birthday' && !birthdayIntroDone;

  useEffect(() => {
    if (isLogin || !chatContainerRef.current) return undefined;
    const viewport = window.visualViewport;
    const updateViewport = () => {
      const height = viewport ? viewport.height : window.innerHeight;
      chatContainerRef.current.style.setProperty('--app-height', `${height}px`);
      setKeyboardOpen(Boolean(viewport && window.innerHeight - viewport.height > 120));
    };
    updateViewport();
    if (viewport) viewport.addEventListener('resize', updateViewport);
    window.addEventListener('resize', updateViewport);
    return () => {
      if (viewport) viewport.removeEventListener('resize', updateViewport);
      window.removeEventListener('resize', updateViewport);
    };
  }, [isLogin]);

  const login = () => {
    if (!user.trim() || !password.trim()) {
      setLoginError('Please enter both username and password.');
      return;
    }
    setLoginError('');
    setLoading(true);
    db.collection('users')
      .where('user', '==', user)
      .where('password', '==', password)
      .get()
      .then(querySnapshot => {
        setLoading(false);
        if (querySnapshot.empty) {
          setLoginError('Invalid username or password.');
          return;
        }
        setIsLogin(false);
        getMessagesFromDB();
      })
      .catch(() => {
        setLoading(false);
        setLoginError('Something went wrong. Please try again.');
      });
  }

  const removeHeartParticle = (id) => {
    setHeartParticles(prev => prev.filter(p => p.id !== id));
  }

  const stopTyping = () => {
    if (typingTimeoutRef.current) {
      clearTimeout(typingTimeoutRef.current);
      typingTimeoutRef.current = null;
    }
    // Only write when we actually told Firestore we were typing, so hitting
    // send right after the idle-timeout already fired doesn't write again.
    if (user && isTypingRef.current) {
      isTypingRef.current = false;
      db.collection(TYPING_COLLECTION).doc(user).set({ typing: false, updatedAt: Date.now() }, { merge: true });
    }
  }

  const handleMessageInputChange = (e) => {
    setMessage(e.target.value);
    if (!user) return;
    // Write typing:true once per burst, not on every keystroke — the idle
    // timeout (reset below) is what eventually writes typing:false.
    if (!isTypingRef.current) {
      isTypingRef.current = true;
      db.collection(TYPING_COLLECTION).doc(user).set({ typing: true, updatedAt: Date.now() }, { merge: true });
    }
    if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
    typingTimeoutRef.current = setTimeout(stopTyping, TYPING_IDLE_MS);
  }

  const markAsRead = useCallback((latestTimestamp) => {
    // Skip the write entirely once this timestamp is already the last one
    // we recorded — handleScroll can call this many times per second while
    // parked at the bottom, but there's nothing new to persist.
    if (!user || !latestTimestamp || latestTimestamp <= lastWrittenReadAtRef.current) return;
    lastWrittenReadAtRef.current = latestTimestamp;
    db.collection(READ_RECEIPTS_COLLECTION).doc(user).set({ lastReadAt: latestTimestamp }, { merge: true });
  }, [user]);

  const toggleReaction = (item, emoji) => {
    const current = item.reactions && item.reactions[user];
    const fieldPath = `reactions.${user}`;
    db.collection('messages').doc(item.id).update({
      [fieldPath]: current === emoji ? firebase.firestore.FieldValue.delete() : emoji,
    });
    setActiveMessageId(null);
  }

  const buildReplyPayload = (item) => ({
    id: item.id,
    user: item.user,
    message: item.message || (item.imageUrl ? 'Photo' : ''),
  });

  const sendMessage = () => {
    const trimmed = message.trim();
    if (!trimmed) return;
    stopTyping();
    const payload = { user, message: trimmed, createdAt: Date.now() };
    if (replyingTo) {
      payload.replyTo = buildReplyPayload(replyingTo);
    }
    db.collection('messages')
      .add(payload)
      .then(() => {
        setMessage('');
        setReplyingTo(null);
      })
  }

  const getMessagesFromDB = () => {
    db.collection('messages')
      .orderBy('createdAt', 'desc')
      .limit(PAGE_SIZE)
      .onSnapshot(querySnapshot => {
        const docs = querySnapshot.docs;
        if (!docs.length) return;

        if (!cursorInitializedRef.current) {
          oldestDocRef.current = docs[docs.length - 1];
          hasMoreRef.current = docs.length === PAGE_SIZE;
          setHasMoreMessages(hasMoreRef.current);
          cursorInitializedRef.current = true;
        }

        const liveMessages = docs.map(doc => ({ id: doc.id, ...doc.data() })).reverse();
        const liveOldestTime = liveMessages[0].createdAt;

        setMessages(prev => {
          const merged = new Map();
          prev.forEach(m => {
            if (m.createdAt < liveOldestTime) merged.set(m.id, m);
          });
          liveMessages.forEach(m => merged.set(m.id, m));
          return Array.from(merged.values()).sort((a, b) => a.createdAt - b.createdAt);
        });
      })
  }

  const loadOlderMessages = async () => {
    if (loadingMore || !hasMoreRef.current || !oldestDocRef.current) return;
    const container = messagesContainerRef.current;
    const prevScrollHeight = container ? container.scrollHeight : 0;
    const prevScrollTop = container ? container.scrollTop : 0;

    setLoadingMore(true);
    try {
      const snap = await db.collection('messages')
        .orderBy('createdAt', 'desc')
        .startAfter(oldestDocRef.current)
        .limit(LOAD_MORE_SIZE)
        .get();

      const docs = snap.docs;
      hasMoreRef.current = docs.length === LOAD_MORE_SIZE;
      setHasMoreMessages(hasMoreRef.current);

      if (docs.length) {
        oldestDocRef.current = docs[docs.length - 1];
        const olderMessages = docs.map(doc => ({ id: doc.id, ...doc.data() })).reverse();
        pendingScrollAdjustRef.current = { prevScrollHeight, prevScrollTop };
        setMessages(prev => {
          const merged = new Map();
          olderMessages.forEach(m => merged.set(m.id, m));
          prev.forEach(m => merged.set(m.id, m));
          return Array.from(merged.values()).sort((a, b) => a.createdAt - b.createdAt);
        });
      }
    } finally {
      setLoadingMore(false);
    }
  }

  const handleScroll = () => {
    const container = messagesContainerRef.current;
    if (!container) return;
    const nearBottom =
      container.scrollHeight - container.scrollTop - container.clientHeight < NEAR_BOTTOM_THRESHOLD;
    isNearBottomRef.current = nearBottom;
    if (nearBottom && messages.length) {
      lastSeenNewestIdRef.current = messages[messages.length - 1].id;
      setHasUnseenMessages(false);
      markAsRead(messages[messages.length - 1].createdAt);
    }
  }

  const handleImageLoad = () => {
    const container = messagesContainerRef.current;
    if (container && isNearBottomRef.current) {
      container.scrollTop = container.scrollHeight;
    }
  }

  const scrollToBottom = () => {
    const container = messagesContainerRef.current;
    if (container) {
      container.scrollTo({ top: container.scrollHeight, behavior: 'smooth' });
    }
    isNearBottomRef.current = true;
    setHasUnseenMessages(false);
    if (messages.length) {
      lastSeenNewestIdRef.current = messages[messages.length - 1].id;
      markAsRead(messages[messages.length - 1].createdAt);
    }
  }

  const handleBubbleTouchStart = (e) => {
    const touch = e.touches[0];
    swipeStateRef.current = { startX: touch.clientX, startY: touch.clientY, dragging: false, dx: 0 };
  }

  const handleBubbleTouchMove = (e) => {
    const state = swipeStateRef.current;
    if (!state || state.cancelled) return;
    const touch = e.touches[0];
    const dx = touch.clientX - state.startX;
    const dy = touch.clientY - state.startY;

    if (!state.dragging) {
      if (Math.abs(dx) < 8 && Math.abs(dy) < 8) return;
      if (Math.abs(dy) > Math.abs(dx)) {
        state.cancelled = true;
        return;
      }
      state.dragging = true;
      suppressClickRef.current = true;
    }

    const clamped = Math.max(-90, Math.min(90, dx));
    state.dx = clamped;
    const bubble = e.currentTarget;
    const bubbleContent = bubble.querySelector('.bubble-content');
    const swipeIcon = bubble.querySelector('.swipe-reply-icon');
    if (bubbleContent) {
      bubbleContent.style.transition = 'none';
      bubbleContent.style.transform = `translateX(${clamped}px)`;
    }
    if (swipeIcon) {
      swipeIcon.style.opacity = Math.min(1, Math.abs(clamped) / SWIPE_REPLY_THRESHOLD);
    }
  }

  const handleBubbleTouchEnd = (e, item) => {
    const state = swipeStateRef.current;
    swipeStateRef.current = null;

    const bubbleContent = e.currentTarget.querySelector('.bubble-content');
    const swipeIcon = e.currentTarget.querySelector('.swipe-reply-icon');
    if (bubbleContent) {
      bubbleContent.style.transition = 'transform 0.2s ease';
      bubbleContent.style.transform = '';
    }
    if (swipeIcon) {
      swipeIcon.style.opacity = 0;
    }

    if (!state || state.cancelled || !state.dragging) return;
    if (Math.abs(state.dx) >= SWIPE_REPLY_THRESHOLD) {
      setReplyingTo(item);
      setActiveMessageId(null);
    }
  }

  useLayoutEffect(() => {
    const container = messagesContainerRef.current;
    if (!container) return;

    const adjust = pendingScrollAdjustRef.current;
    if (adjust) {
      container.scrollTop = container.scrollHeight - adjust.prevScrollHeight + adjust.prevScrollTop;
      pendingScrollAdjustRef.current = null;
      return;
    }

    const newestMessage = messages[messages.length - 1];

    if (isInitialLoadRef.current) {
      if (!messages.length) return;
      container.scrollTop = container.scrollHeight;
      isInitialLoadRef.current = false;
      isNearBottomRef.current = true;
      lastSeenNewestIdRef.current = newestMessage.id;
      markAsRead(newestMessage.createdAt);
      return;
    }

    if (isNearBottomRef.current) {
      container.scrollTop = container.scrollHeight;
      if (newestMessage) {
        lastSeenNewestIdRef.current = newestMessage.id;
        markAsRead(newestMessage.createdAt);
      }
      setHasUnseenMessages(false);
    } else if (newestMessage && newestMessage.id !== lastSeenNewestIdRef.current) {
      // The newest message changed while we're scrolled up reading history —
      // a genuinely new incoming message, not just a reaction/edit on an
      // older one (those don't move the tail of the array).
      lastSeenNewestIdRef.current = newestMessage.id;
      setHasUnseenMessages(true);
    }
  }, [messages, markAsRead]);

  useEffect(() => {
    if (isLogin || !user) return;
    const unsubscribe = db.collection(TYPING_COLLECTION).onSnapshot(snapshot => {
      const now = Date.now();
      const others = snapshot.docs
        .map(doc => ({ id: doc.id, ...doc.data() }))
        .filter(t => t.id !== user && t.typing && (now - (t.updatedAt || 0)) < TYPING_STALE_MS);
      setTypingUsers(others.map(t => t.id));
    });
    return unsubscribe;
  }, [isLogin, user]);

  useEffect(() => {
    if (isLogin) return;
    const unsubscribe = db.collection(READ_RECEIPTS_COLLECTION).onSnapshot(snapshot => {
      const receipts = {};
      snapshot.docs.forEach(doc => { receipts[doc.id] = doc.data().lastReadAt || 0; });
      setReadReceipts(receipts);
    });
    return unsubscribe;
  }, [isLogin]);

  useEffect(() => {
    if (!specialDate || specialDate.id === 'birthday') return;
    const pool = specialDate.particles;
    const spawnHeart = () => {
      setHeartParticles(prev => [...prev.slice(-40), {
        id: ++heartIdRef.current,
        emoji: pool[Math.floor(Math.random() * pool.length)],
        left: Math.random() * 100,
        duration: 5 + Math.random() * 4,
      }]);
    };
    spawnHeart();
    const interval = setInterval(spawnHeart, 1100);
    return () => clearInterval(interval);
  }, [specialDate]);

  // Push notifications are deliberately restricted to one recipient — see
  // functions/index.js, which only ever sends to this same username.
  useEffect(() => {
    if (isLogin || user !== NOTIFICATIONS_ENABLED_USER) return;
    if (!('serviceWorker' in navigator) || typeof Notification === 'undefined') return;
    if (!FCM_VAPID_KEY) return;

    let cancelled = false;

    const setupPushNotifications = async () => {
      try {
        const registration = await navigator.serviceWorker.register(`${process.env.PUBLIC_URL}/firebase-messaging-sw.js`);
        const messagingInstance = getMessagingInstance();
        if (!messagingInstance || cancelled) return;

        const permission = await Notification.requestPermission();
        if (permission !== 'granted' || cancelled) return;

        const token = await messagingInstance.getToken({
          vapidKey: FCM_VAPID_KEY,
          serviceWorkerRegistration: registration,
        });
        if (token && !cancelled) {
          await db.collection('fcmTokens').doc(NOTIFICATIONS_ENABLED_USER).set({
            token,
            updatedAt: Date.now(),
          });
        }

        messagingInstance.onMessage((payload) => {
          const { title, body } = payload.notification || {};
          if (title) {
            new Notification(title, { body, icon: `${process.env.PUBLIC_URL}/logo192.png` });
          }
        });
      } catch (err) {
        // Notifications are a nice-to-have; never let setup failures affect
        // the rest of the chat.
        console.error('Push notification setup failed:', err);
      }
    };

    setupPushNotifications();
    return () => { cancelled = true; };
  }, [isLogin, user]);

  const otherLastReadAt = Object.entries(readReceipts)
    .filter(([name]) => name !== user)
    .reduce((max, [, value]) => Math.max(max, value), 0);

  let lastDateKey = null;
  const messageElements = messages.map((item) => {
    const dateKey = moment(item.createdAt).format('YYYY-MM-DD');
    const showDivider = dateKey !== lastDateKey;
    lastDateKey = dateKey;
    const isMe = item.user === user;
    const reactionCounts = {};
    Object.values(item.reactions || {}).forEach(e => { reactionCounts[e] = (reactionCounts[e] || 0) + 1; });

    return (
      <Fragment key={item.id}>
        {showDivider && (
          <div className="date-divider"><span>{getDayLabel(item.createdAt)}</span></div>
        )}
        <div
          className={`message-bubble ${isMe ? 'me' : 'them'}`}
          onTouchStart={handleBubbleTouchStart}
          onTouchMove={handleBubbleTouchMove}
          onTouchEnd={(e) => handleBubbleTouchEnd(e, item)}
        >
          <span className="swipe-reply-icon" aria-hidden="true"><i className="fa fa-reply"></i></span>
          <div className="bubble-content">
            <div
              className="bubble-tap-target"
              onClick={() => {
                if (suppressClickRef.current) {
                  suppressClickRef.current = false;
                  return;
                }
                setActiveMessageId(prev => prev === item.id ? null : item.id);
              }}
            >
              {item.replyTo && (
                <div className="reply-quote">
                  <strong>{item.replyTo.user === user ? 'You' : item.replyTo.user}</strong>
                  <span>{item.replyTo.message}</span>
                </div>
              )}
              {item.imageUrl && (
                <img
                  className="message-image"
                  src={item.imageUrl}
                  alt=""
                  onLoad={handleImageLoad}
                />
              )}
              {item.message && <span className="message">{forceEmojiPresentation(item.message)}</span>}
            </div>
            <div className="time">
              {moment(item.createdAt).format('h:mm A')}
              {isMe && (
                <span className={`read-tick${otherLastReadAt >= item.createdAt ? ' seen' : ''}`}>✓✓</span>
              )}
            </div>
            {Object.keys(reactionCounts).length > 0 && (
              <div className="reaction-badges">
                {Object.entries(reactionCounts).map(([emoji, count]) => (
                  <span className="reaction-badge" key={emoji}>{emoji}{count > 1 ? count : ''}</span>
                ))}
              </div>
            )}
            {activeMessageId === item.id && (
              <div className={`message-toolbar ${isMe ? 'align-right' : 'align-left'}`}>
                {QUICK_REACTIONS.map(emoji => (
                  <button
                    key={emoji}
                    className="toolbar-emoji"
                    onClick={() => toggleReaction(item, emoji)}
                  >{emoji}</button>
                ))}
                <button
                  className="toolbar-reply"
                  onClick={() => { setReplyingTo(item); setActiveMessageId(null); }}
                  title="Reply"
                >
                  <i className="fa fa-reply" aria-hidden="true"></i>
                </button>
              </div>
            )}
          </div>
        </div>
      </Fragment>
    )
  });

  return (
    <div className={`app-root${specialDate ? ' ' + specialDate.themeClass : ''}`}>
      {specialDate && specialDate.id === 'birthday' && <BirthdayFireworks />}
      {specialDate && specialDate.id !== 'birthday' && (
        <div className="particle-layer" aria-hidden="true">
          {heartParticles.map(p => (
            <span
              key={p.id}
              className="floating-particle"
              style={{ left: `${p.left}%`, animationDuration: `${p.duration}s` }}
              onAnimationEnd={() => removeHeartParticle(p.id)}
            >{p.emoji}</span>
          ))}
        </div>
      )}

      {showBirthdayIntro && <BirthdayIntro onContinue={() => setBirthdayIntroDone(true)} />}

      {isLogin && !showBirthdayIntro && (
        <div className="app-container">
          <div className="login-card">
            {specialDate && <div className="anniversary-tag">{specialDate.loginTag}</div>}
            <div className="login-brand">ChitChat</div>
            <div className="login-tagline">Sign in to keep the conversation going</div>
            <div className="input-container">
              <input type="text" placeholder="User Name" value={user} onChange={(e) => setUser(e.target.value)} />
              <input type="password" placeholder="Password" value={password} onChange={(e) => setPassword(e.target.value)} />
              {loginError && <div className="login-error">{loginError}</div>}
              <button className="login-button" disabled={loading} onClick={login}>
                {loading ? <BarLoader color="#06140f" width={40} height={3} /> : 'Sign In'}
              </button>
            </div>
          </div>
        </div>
      )}

      {!isLogin &&
        <div ref={chatContainerRef} className={`chat-container${keyboardOpen ? ' keyboard-open' : ''}`}>
          {specialDate && <div className="anniversary-banner">{specialDate.banner}</div>}

          <div className="chat-body">
            <VideoCall user={user} buttonTarget={callButtonTarget} />
            <div className="chat-messages" ref={messagesContainerRef} onScroll={handleScroll}>
              {hasMoreMessages && (
                loadingMore ? (
                  <div className="messages-loading">
                    <BarLoader color="#d8b46a" width={60} height={3} />
                  </div>
                ) : (
                  <button className="load-more-button" onClick={loadOlderMessages}>
                    Load older messages
                  </button>
                )
              )}
              {messageElements}
              {typingUsers.length > 0 && (
                <div className="typing-indicator" role="status" aria-live="polite">
                  <span>{typingUsers.join(', ')} is typing</span>
                  <i><b></b><b></b><b></b></i>
                </div>
              )}
            </div>

            {hasUnseenMessages && (
              <button className="scroll-to-bottom-pill" onClick={scrollToBottom}>
                <i className="fa fa-arrow-down" aria-hidden="true"></i> New message
              </button>
            )}

            {replyingTo && (
              <div className="reply-preview">
                <div className="reply-preview-text">
                  <strong>{replyingTo.user === user ? 'You' : replyingTo.user}</strong>
                  <span>{replyingTo.message || (replyingTo.imageUrl ? 'Photo' : '')}</span>
                </div>
                <button className="reply-preview-close" onClick={() => setReplyingTo(null)}>
                  <i className="fa fa-times" aria-hidden="true"></i>
                </button>
              </div>
            )}

            <div className="chat-input">
              <div className="call-button-slot" ref={setCallButtonTarget} />
              <input
                type="text"
                value={message}
                onChange={handleMessageInputChange}
                placeholder="Type something..."
                onKeyUp={(e) => { if (e.key === 'Enter') { sendMessage() } }}
              />
              <button className="chat-send" disabled={!message.trim()} onClick={sendMessage}>
                <i className="fa fa-lg fa-paper-plane" aria-hidden="true"></i>
              </button>
            </div>

          </div>
        </div>
      }
    </div>
  );
}

export default App;
