import { useEffect, useRef } from 'react';

const COLORS = ['#ff6b7f', '#ffd166', '#6ee7d8', '#a78bfa', '#ff9f68', '#f8f5e8'];

function BirthdayFireworks() {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const context = canvas.getContext('2d');
    const motionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
    let width = 0;
    let height = 0;
    let frame = 0;
    let timer = 0;
    let lastLaunch = 0;
    let nextLaunch = 250;
    let rockets = [];
    let particles = [];

    const resize = () => {
      const pixelRatio = Math.min(window.devicePixelRatio || 1, 1);
      width = window.innerWidth;
      height = window.innerHeight;
      canvas.width = Math.round(width * pixelRatio);
      canvas.height = Math.round(height * pixelRatio);
      canvas.style.width = `${width}px`;
      canvas.style.height = `${height}px`;
      context.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);
    };

    const burst = (x, y, color) => {
      const count = 22 + Math.floor(Math.random() * 12);
      const baseAngle = Math.random() * Math.PI * 2;
      for (let index = 0; index < count; index += 1) {
        const angle = baseAngle + (Math.PI * 2 * index) / count + (Math.random() - 0.5) * 0.12;
        const speed = 1.1 + Math.random() * 3.1;
        particles.push({
          x,
          y,
          vx: Math.cos(angle) * speed,
          vy: Math.sin(angle) * speed,
          life: 34 + Math.random() * 18,
          age: 0,
          size: 1 + Math.random() * 1.8,
          color: Math.random() > 0.28 ? color : COLORS[Math.floor(Math.random() * COLORS.length)],
          sparkle: Math.random() > 0.7,
        });
      }
      if (particles.length > 180) particles.splice(0, particles.length - 180);
    };

    const launch = () => {
      const x = width * (0.08 + Math.random() * 0.84);
      const targetY = height * (0.13 + Math.random() * 0.43);
      rockets.push({
        x,
        y: height + 8,
        targetY,
        vx: (Math.random() - 0.5) * 1.1,
        vy: -(6.2 + Math.random() * 2.3),
        color: COLORS[Math.floor(Math.random() * COLORS.length)],
        trail: [],
      });
    };

    const draw = (time) => {
      context.globalCompositeOperation = 'destination-out';
      context.fillStyle = 'rgba(5, 8, 13, 0.2)';
      context.fillRect(0, 0, width, height);
      context.globalCompositeOperation = 'lighter';

      if (!motionQuery.matches && time - lastLaunch > nextLaunch) {
        launch();
        lastLaunch = time;
        nextLaunch = 1250 + Math.random() * 1000;
      }

      rockets = rockets.filter((rocket) => {
        rocket.trail.push({ x: rocket.x, y: rocket.y });
        if (rocket.trail.length > 7) rocket.trail.shift();
        rocket.x += rocket.vx;
        rocket.y += rocket.vy;
        rocket.vy += 0.035;

        context.globalAlpha = 0.5;
        context.fillStyle = rocket.color;
        context.beginPath();
        rocket.trail.forEach((point, index) => {
          context.arc(point.x, point.y, 1.2 + index * 0.12, 0, Math.PI * 2);
        });
        context.fill();
        context.globalAlpha = 1;
        context.fillStyle = '#fff8df';
        context.beginPath();
        context.arc(rocket.x, rocket.y, 2, 0, Math.PI * 2);
        context.fill();

        if (rocket.y <= rocket.targetY || rocket.vy >= -0.5) {
          burst(rocket.x, rocket.y, rocket.color);
          return false;
        }
        return true;
      });

      const batches = new Map();
      particles = particles.filter((particle) => {
        particle.age += 1;
        particle.x += particle.vx;
        particle.y += particle.vy;
        particle.vx *= 0.985;
        particle.vy = particle.vy * 0.985 + 0.035;
        const remaining = 1 - particle.age / particle.life;
        const opacity = Math.ceil(remaining * (particle.sparkle && particle.age % 8 < 4 ? 0.45 : 1) * 5) / 5;
        const key = `${particle.color}:${opacity}`;
        let batch = batches.get(key);
        if (!batch) {
          batch = { color: particle.color, opacity, points: [] };
          batches.set(key, batch);
        }
        batch.points.push(particle);
        return particle.age < particle.life;
      });

      batches.forEach((batch) => {
        context.globalAlpha = batch.opacity;
        context.fillStyle = batch.color;
        context.beginPath();
        batch.points.forEach((particle) => {
          const remaining = 1 - particle.age / particle.life;
          context.moveTo(particle.x + particle.size, particle.y);
          context.arc(particle.x, particle.y, particle.size * Math.max(0.35, remaining), 0, Math.PI * 2);
        });
        context.fill();
      });

      context.globalAlpha = 1;
      timer = window.setTimeout(() => {
        frame = window.requestAnimationFrame(draw);
      }, 42);
    };

    if (motionQuery.matches) return undefined;
    resize();
    frame = window.requestAnimationFrame(draw);
    window.addEventListener('resize', resize);
    return () => {
      window.cancelAnimationFrame(frame);
      window.clearTimeout(timer);
      window.removeEventListener('resize', resize);
    };
  }, []);

  return <canvas ref={canvasRef} className="birthday-fireworks" aria-hidden="true" />;
}

export default BirthdayFireworks;