import { useEffect, useRef, useState } from 'react';

const CONFETTI = Array.from({ length: 36 }, (_, index) => ({
  id: index,
  left: `${(index * 37) % 100}%`,
  delay: `${(index % 9) * 0.11}s`,
  duration: `${2.4 + (index % 7) * 0.18}s`,
  color: ['#ff4f81', '#ffd166', '#39d6c5', '#8b6cff', '#ff914d'][index % 5],
  rotation: `${(index * 53) % 360}deg`,
}));

function BirthdayIntro({ onContinue }) {
  const [celebrated, setCelebrated] = useState(false);
  const [listening, setListening] = useState(false);
  const [micStarting, setMicStarting] = useState(false);
  const [micMessage, setMicMessage] = useState('');
  const streamRef = useRef(null);
  const audioContextRef = useRef(null);
  const intervalRef = useRef(null);
  const micMeterRef = useRef(null);
  const puffCountRef = useRef(0);
  const noiseFloorRef = useRef(0.001);

  const stopMicrophone = () => {
    if (intervalRef.current) window.clearInterval(intervalRef.current);
    intervalRef.current = null;
    if (streamRef.current) streamRef.current.getTracks().forEach(track => track.stop());
    streamRef.current = null;
    if (audioContextRef.current && audioContextRef.current.state !== 'closed') {
      audioContextRef.current.close().catch(() => {});
    }
    audioContextRef.current = null;
  };

  const celebrate = () => {
    stopMicrophone();
    setListening(false);
    setCelebrated(true);
  };

  useEffect(() => () => stopMicrophone(), []);

  const startMicrophone = async () => {
    if (micStarting || listening) return;
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      setMicMessage('Microphone access needs a secure page and browser permission. Tap the candles instead.');
      return;
    }

    let stream;
    let audioContext;
    let streamPromise;
    setMicStarting(true);
    setMicMessage('Starting microphone...');
    try {
      const AudioContextClass = window.AudioContext || window.webkitAudioContext;
      if (!AudioContextClass) {
        setMicStarting(false);
        setMicMessage('Audio detection is not supported here. Tap the candles to blow them out.');
        return;
      }

      streamPromise = navigator.mediaDevices.getUserMedia({
        audio: { echoCancellation: false, noiseSuppression: false, autoGainControl: false },
      });
      audioContext = new AudioContextClass();
      audioContextRef.current = audioContext;
      const resumePromise = audioContext.resume();
      [stream] = await Promise.all([streamPromise, resumePromise]);
      streamRef.current = stream;
      const analyser = audioContext.createAnalyser();
      analyser.fftSize = 512;
      analyser.smoothingTimeConstant = 0;
      const source = audioContext.createMediaStreamSource(stream);
      const silentOutput = audioContext.createGain();
      silentOutput.gain.value = 0;
      source.connect(analyser);
      analyser.connect(silentOutput);
      silentOutput.connect(audioContext.destination);
      const samples = new Float32Array(analyser.fftSize);
      puffCountRef.current = 0;
      noiseFloorRef.current = 0.001;
      let calibrationSamples = 0;
      const calibrationVolumes = [];
      setMicStarting(false);
      setListening(true);
      setMicMessage('Listening. Any small sound near your microphone will do.');

      intervalRef.current = window.setInterval(() => {
        analyser.getFloatTimeDomainData(samples);
        let sum = 0;
        for (let index = 0; index < samples.length; index += 1) {
          sum += samples[index] * samples[index];
        }
        const volume = Math.sqrt(sum / samples.length);
        if (micMeterRef.current) {
          micMeterRef.current.style.transform = `scaleX(${Math.min(1, volume * 18)})`;
        }
        if (calibrationSamples < 5) {
          const startupThreshold = Math.max(0.003, noiseFloorRef.current * 1.6);
          if (volume > startupThreshold) {
            puffCountRef.current += 1;
            if (puffCountRef.current >= 2) {
              celebrate();
              return;
            }
          } else {
            puffCountRef.current = 0;
          }
          calibrationVolumes.push(volume);
          calibrationSamples += 1;
          if (calibrationSamples === 5) {
            noiseFloorRef.current = Math.min(...calibrationVolumes);
          }
          return;
        }
        const threshold = Math.max(0.0015, noiseFloorRef.current * 1.1);
        if (volume > threshold) {
          puffCountRef.current += 1;
        } else {
          puffCountRef.current = 0;
          noiseFloorRef.current = noiseFloorRef.current * 0.97 + volume * 0.03;
        }
        if (puffCountRef.current >= 2) celebrate();
      }, 50);
    } catch (error) {
      if (stream) stream.getTracks().forEach(track => track.stop());
      stopMicrophone();
      if (micMeterRef.current) micMeterRef.current.style.transform = 'scaleX(0)';
      setMicStarting(false);
      setListening(false);
      setMicMessage(error.name === 'NotAllowedError' || error.name === 'PermissionDeniedError'
        ? 'Microphone permission was blocked. Allow it in browser settings, or tap the candles instead.'
        : error.name === 'NotFoundError'
          ? 'No microphone was found. Tap the candles to blow them out.'
          : 'Could not start the microphone. Check browser permission or tap the candles instead.');
    }
  };

  return (
    <main className={`birthday-intro${celebrated ? ' is-celebrated' : ''}`}>
      {celebrated && (
        <div className="birthday-confetti" aria-hidden="true">
          {CONFETTI.map(piece => (
            <span
              key={piece.id}
              style={{
                left: piece.left,
                animationDelay: piece.delay,
                animationDuration: piece.duration,
                backgroundColor: piece.color,
                '--confetti-rotation': piece.rotation,
              }}
            />
          ))}
        </div>
      )}

      <div className="birthday-intro-content">
        {!celebrated && <div className="birthday-eyebrow">A little birthday magic</div>}
        {!celebrated ? (
          <>
            <h1 className="birthday-intro-title">Make a wish, Baby!</h1>
            <p className="birthday-intro-copy">One big breath, then the wish is yours. <br/>Universe is listening</p>
          </>
        ) : (
          <div className="birthday-greeting" role="status" aria-live="polite">
            <span className="birthday-greeting-kicker">Your wish is on its way</span>
            <h1>Happy Birthday, Baby!</h1>
            <p>May the universe gift you everything you've been wishing for Baby !!</p>
            <button className="birthday-continue" onClick={onContinue}>Continue to login</button>
          </div>
        )}

        <div className={`birthday-cake-scene${celebrated ? ' candles-out' : ''}`}>
          <div className="birthday-cake-art">
            <div className="cake-sparkle sparkle-one">✦</div>
            <div className="cake-sparkle sparkle-two">✧</div>
            <div className="cake-sparkle sparkle-three">✦</div>
            <div className="birthday-candles" aria-label={celebrated ? 'Candles blown out' : 'Lit birthday candles'}>
              {[0, 1, 2, 3, 4].map(candle => (
                <span className={`birthday-candle candle-${candle + 1}`} key={candle}>
                  {!celebrated && <i className="candle-flame" />}
                </span>
              ))}
            </div>
            <div className="birthday-cake cake-top"><i /><i /><i /><i /><i /></div>
            <div className="birthday-cake cake-middle"><i /><i /><i /><i /></div>
            <div className="birthday-cake cake-bottom"><i /><i /><i /><i /><i /></div>
            <div className="cake-plate" />
          </div>
        </div>

        {!celebrated && (
          <div className="birthday-actions">
            {micStarting ? (
              <div className="listening-indicator" role="status"><span /> Starting microphone</div>
            ) : listening ? (
              <div className="listening-indicator" role="status">
                <span /> Listening for your wish
                <i className="mic-input-meter" aria-hidden="true"><i ref={micMeterRef} /></i>
              </div>
            ) : (
              <button className="birthday-blow-button" onClick={startMicrophone}>
                <span aria-hidden="true">♫</span> Blow out the candles
              </button>
            )}
            {/* <button className="birthday-tap-button" onClick={celebrate}>Tap to blow them out</button> */}
            {micMessage && <p className="birthday-mic-message" role="status">{micMessage}</p>}
          </div>
        )}
      </div>

      <button className="birthday-skip" onClick={onContinue}>Skip to login <span aria-hidden="true">→</span></button>
    </main>
  );
}

export default BirthdayIntro;